source='''from collections import Counter

def transform(grid):
    out = [row[:] for row in grid]
    points = [(r, c) for r, row in enumerate(grid) for c, value in enumerate(row) if value == 2]
    row_counts = Counter(r for r, c in points)
    col_counts = Counter(c for r, c in points)
    if max(row_counts.values(), default=0) >= max(col_counts.values(), default=0):
        spine = next(r for r, n in row_counts.items() if n == max(row_counts.values()))
        for c in range(min(c for r, c in points), max(c for r, c in points) + 1):
            if out[spine][c] == 0:
                out[spine][c] = 3
        for r, c in points:
            for rr in range(min(r, spine), max(r, spine) + 1):
                if out[rr][c] == 0:
                    out[rr][c] = 3
    else:
        spine = next(c for c, n in col_counts.items() if n == max(col_counts.values()))
        for r in range(min(r for r, c in points), max(r for r, c in points) + 1):
            if out[r][spine] == 0:
                out[r][spine] = 3
        for r, c in points:
            for cc in range(min(c, spine), max(c, spine) + 1):
                if out[r][cc] == 0:
                    out[r][cc] = 3
    return out
'''
