def grid_from_points(h,w,pts):
    g=[[0]*w for _ in range(h)]
    for r,c in pts:g[r][c]=2
    return g

def cells3(g): return {(r,c) for r,row in enumerate(g) for c,v in enumerate(row) if v==3}
